#!/usr/bin/env Rscript
# Core conclusion: fixed discovery priorities fail external ranking despite selected axis conservation.
# Evidence chain: all-gene external effects -> matched simple baseline -> complete axis follow-up.
# Quantitative grid,183mm;R-only vector/preview exports;no image edits or outcome-selected genes.
suppressPackageStartupMessages({library(data.table);library(ggplot2);library(patchwork);library(ggrepel)})
a<-commandArgs(TRUE);file_arg<-grep('^--file=',commandArgs(FALSE),value=TRUE);script_dir<-dirname(normalizePath(sub('^--file=','',file_arg)));work<-if(length(a))normalizePath(a[1])else script_dir;if(!file.exists(file.path(work,'gene.tsv.gz')))work<-file.path(work,'paper19opp-revision2/reconstruction/candidate_validation');final<-if(length(a)>1)a[2]else file.path(work,'Fig_independent_candidate_validation.pdf')
theme_set(theme_classic(base_size=7,base_family='Helvetica')+theme(axis.line=element_line(linewidth=.35),axis.ticks=element_line(linewidth=.35),axis.text=element_text(size=6.4),axis.title=element_text(size=7),legend.title=element_text(size=6.4),legend.text=element_text(size=6.1),plot.title=element_text(size=7,face='plain'),plot.tag=element_text(size=8,face='bold'),plot.margin=margin(5,5,5,5),panel.grid=element_blank()))
g<-fread(file.path(work,'gene.tsv.gz'));m<-fread(file.path(work,'metric.tsv.gz'));co<-fread(file.path(work,'exploratory_axis_conservation.tsv'))
scatter<-function(st,ctx){
 z<-g[study==st&context==ctx];setorderv(z,c('priority_score','gene'),c(-1,1));z[,top10:=seq_len(.N)<=10]
 ggplot(z,aes(priority_score,directional_effect))+geom_hline(yintercept=0,linetype=2,linewidth=.35,colour='#9B9B9B')+geom_point(aes(colour=top10),size=1.8,alpha=.9)+geom_text_repel(data=z[top10==TRUE],aes(label=gene),seed=20261106,size=2.2,max.overlaps=Inf,box.padding=.25,point.padding=.15,min.segment.length=0,segment.size=.2,colour='#2B2B2B')+scale_colour_manual(values=c('FALSE'='#B0B0B0','TRUE'='#4C78A8'),labels=c('Other assayed genes','Top 10 priorities'))+scale_x_continuous(expand=expansion(mult=c(.03,.13)))+labs(x='Discovery priority score',y='Independent signed program shift (control SD)',colour=NULL)+theme(legend.position='none')
}
pA<-scatter('Adamson2016','Adamson_K562_UPR')+labs(title='Independent K562 study (30 genes)')
pB<-scatter('Frangieh2021','Control')+labs(title='Melanoma, unstimulated (19 genes)')
fm<-m[outcome=='directional_effect'&study%in%c('Adamson2016','Frangieh2021')&method%in%c('Composite priority','Dominant-program magnitude')]
fm[,cohort:=fifelse(study=='Adamson2016','K562 / Adamson (30)',fifelse(context=='Control','Melanoma / control (19)',fifelse(context=='IFNγ','Melanoma / IFNγ (19)','Melanoma / co-culture (17)')))]
fm[,cohort:=factor(cohort,levels=rev(c('K562 / Adamson (30)','Melanoma / control (19)','Melanoma / IFNγ (19)','Melanoma / co-culture (17)')))]
fm[,method:=factor(method,levels=c('Composite priority','Dominant-program magnitude'))]
pC<-ggplot(fm,aes(spearman,cohort,colour=method))+geom_vline(xintercept=0,linetype=2,colour='#999999',linewidth=.35)+geom_errorbar(aes(xmin=conditional_gene_bootstrap_low,xmax=conditional_gene_bootstrap_high),position=position_dodge(width=.5),orientation='y',width=.12,linewidth=.4)+geom_point(position=position_dodge(width=.5),size=1.8)+scale_colour_manual(values=c('Composite priority'='#4C78A8','Dominant-program magnitude'='#909090'),labels=c('Composite priority','Magnitude only'))+scale_x_continuous(limits=c(-1,1),breaks=c(-1,-.5,0,.5,1))+labs(x='Priority–response Spearman correlation',y=NULL,colour=NULL,caption='Integrated-score coverage: 12/30 K562 genes;\n4/19 melanoma genes.')+theme(legend.position='bottom',legend.box='vertical',plot.caption=element_text(size=6,hjust=0),axis.text.y=element_text(size=6.3))+guides(colour=guide_legend(nrow=2,byrow=TRUE))
axis_order<-c('apoptosis','proliferation','stress','hallmark_UNFOLDED_PROTEIN_RESPONSE','hallmark_E2F_TARGETS','hallmark_G2M_CHECKPOINT','hallmark_P53_PATHWAY','hallmark_TNFA_SIGNALING_VIA_NFKB','hallmark_INTERFERON_GAMMA_RESPONSE','hallmark_MTORC1_SIGNALING','hallmark_OXIDATIVE_PHOSPHORYLATION','hallmark_HYPOXIA')
axis_labels<-c('Apoptosis','Proliferation','Stress','UPR','E2F targets','G2M checkpoint','p53 pathway','TNF / NFκB','IFNγ response','mTORC1','OXPHOS','Hypoxia')
co[,axis:=factor(axis,levels=rev(axis_order))];co[,cohort:=fifelse(study=='Adamson2016','K562\nAdamson',fifelse(context=='Control','Melanoma\ncontrol',fifelse(context=='IFNγ','Melanoma\nIFNγ','Melanoma\nco-culture')))]
co[,cohort:=factor(cohort,levels=c('K562\nAdamson','Melanoma\ncontrol','Melanoma\nIFNγ','Melanoma\nco-culture'))]
co[,label:=paste0(sprintf('%.2f',spearman),fifelse(BH_q_all_48<.05,'*',''))]
pD<-ggplot(co,aes(cohort,axis,fill=spearman))+geom_tile(colour='white',linewidth=.4)+geom_text(aes(label=label),size=1.9)+scale_fill_gradient2(low='#D9A16B',mid='#FFFFFF',high='#4C78A8',midpoint=0,limits=c(-1,1),breaks=c(-1,0,1))+scale_y_discrete(labels=setNames(axis_labels,axis_order))+labs(x=NULL,y=NULL,fill='Spearman ρ',caption='Exploratory, full-support axis correlations;\n*BH q < 0.05 across all 48 tests.')+theme(axis.line=element_blank(),axis.ticks=element_blank(),axis.text.y=element_text(size=6),axis.text.x=element_text(size=5.7),legend.position='bottom',legend.key.width=grid::unit(6,'mm'),legend.key.height=grid::unit(2,'mm'),plot.caption=element_text(size=6,hjust=0))
fig<-pA+pB+pC+pD+plot_layout(design='AB\nCD',widths=c(1,1.05),heights=c(1,1.1))+plot_annotation(tag_levels='a')&theme(plot.tag=element_text(size=8,face='bold'))
dir.create(dirname(final),recursive=TRUE,showWarnings=FALSE);if(Sys.info()[['sysname']]=='Darwin')quartz(type='pdf',file=final,width=183/25.4,height=188/25.4,family='Helvetica')else cairo_pdf(final,width=183/25.4,height=188/25.4,family='Helvetica');print(fig);dev.off()
svglite::svglite(file.path(work,'Fig_independent_candidate_validation.svg'),width=183/25.4,height=188/25.4);print(fig);dev.off()
ragg::agg_png(file.path(work,'Fig_independent_candidate_validation_preview.png'),width=183,height=188,units='mm',res=180);print(fig);dev.off()
fwrite(g[(study=='Adamson2016'&context=='Adamson_K562_UPR')|(study=='Frangieh2021'&context=='Control'),.(panel=fifelse(study=='Adamson2016','a','b'),study,context,gene,priority_score,target_program,target_sign,directional_effect)],file.path(work,'Fig_independent_candidate_validation_scatter_data.tsv'),sep='\t')
fwrite(fm,file.path(work,'Fig_independent_candidate_validation_forest_data.tsv'),sep='\t');fwrite(co,file.path(work,'Fig_independent_candidate_validation_axis_data.tsv'),sep='\t')
